#pragma once
#include "RawImageBackdropDisplayShaders.h"
#include <string>

namespace Stack::Renderer::RawImageBackdropNoiseShaders {
// Autocorrelation of the exact unit-variance fields generated by Seed:
// white, separable [1,2,1]/sqrt(6), and [1,4,6,4,1]/sqrt(70).
inline constexpr const char* BandStatistics = R"(
float grainCorrelation(int band, int lag) {
    if (lag == 0) return 1.0;
    if (band == 0) return 0.0;
    if (band == 1) return lag == 1 ? 2.0/3.0 : lag == 2 ? 1.0/6.0 : 0.0;
    if (lag == 1) return .8;
    if (lag == 2) return .4;
    if (lag == 3) return 8.0/70.0;
    return lag == 4 ? 1.0/70.0 : 0.0;
}
)";

inline const std::string Analysis = std::string(R"(#version 430 core
layout(local_size_x=8,local_size_y=8) in;
layout(rgba32f,binding=0) writeonly uniform image2DArray varianceOutput;
layout(rgba32f,binding=1) writeonly uniform image2DArray covarianceOutput;
uniform sampler2D image, previous;
uniform vec4 rect, textureRect;
uniform vec2 previousOffset, previousScale, nativeExtent;
uniform float fadeAmount;
uniform bool encodedSrgb, clearOnly;
)") + RawImageBackdropDisplayShaders::Functions + BandStatistics + R"(
vec4 samplePhoto(vec2 p) {
    // Measurements lie on source texel centers. Clamp each display texel
    // before any previous-frame interpolation, matching the photo surround.
    ivec2 extent=textureSize(image,0);
    vec4 b=backdropVisibleTexel(image,clamp(ivec2(floor(p*vec2(extent))),ivec2(0),extent-1));
    if (fadeAmount < 1.0) {
        vec4 a=backdropVisibleSample(previous,previousOffset+p*previousScale);
        float alpha=mix(a.a,b.a,fadeAmount);
        vec3 ar=encodedSrgb ? backdropDisplayDecode(a.rgb) : a.rgb;
        vec3 br=encodedSrgb ? backdropDisplayDecode(b.rgb) : b.rgb;
        vec3 rgb=alpha>.000001 ? mix(ar*a.a,br*b.a,fadeAmount)/alpha : vec3(0);
        b=vec4(encodedSrgb ? backdropDisplayEncode(rgb) : rgb,alpha);
    }
    b.rgb=backdropDisplayRange(b.rgb);
    return b;
}
vec3 noiseComponents(vec3 rgb) {
    return vec3((rgb.r+rgb.g+rgb.b)*.5773502692,
                (rgb.r-rgb.b)*.7071067812,
                (rgb.r-2.0*rgb.g+rgb.b)*.4082482905);
}
void sort16(inout vec3 values[16]) {
    for (int span=2;span<=16;span*=2)
        for (int stride=span/2;stride>0;stride/=2)
            for (int i=0;i<16;++i) {
                int j=i^stride;
                if (j>i) {
                    vec3 lo=min(values[i],values[j]),hi=max(values[i],values[j]);
                    bool ascending=(i&span)==0;
                    values[i]=ascending ? lo : hi;
                    values[j]=ascending ? hi : lo;
                }
            }
}
void robustMoments(vec3 values[16],out vec3 variance,out vec3 correlation) {
    vec3 sorted[16];
    for (int i=0;i<16;++i) sorted[i]=values[i];
    sort16(sorted);
    vec3 center=.5*(sorted[7]+sorted[8]);
    for (int i=0;i<16;++i) sorted[i]=abs(values[i]-center);
    sort16(sorted);
    vec3 sigma=.5*(sorted[7]+sorted[8])*(1.4826022185*16.0/15.2);
    variance=sigma*sigma;
    vec3 sum=vec3(0),squared=vec3(0),crossTerms=vec3(0);
    for (int i=0;i<16;++i) {
        // Winsorize structure before estimating relationships between colors.
        // A common set of vectors gives a positive-semidefinite covariance.
        vec3 z=clamp((values[i]-center)/max(sigma,vec3(1e-8)),vec3(-2.5),vec3(2.5));
        sum+=z; squared+=z*z; crossTerms+=z.xxy*z.yzz;
    }
    squared=max(vec3(0),squared-sum*sum/16.0);
    crossTerms-=sum.xxy*sum.yzz/16.0;
    correlation=clamp(crossTerms/sqrt(max(vec3(1e-16),squared.xxy*squared.yzz)),vec3(-1),vec3(1));
}
float averagedCovariance(int band,float footprint,float lag) {
    float sum=0.0;
    // Exact box-average pair counts for integer footprints; a bounded
    // interpolation for fractional proxies. Lost native detail is not known.
    for (int d=-4;d<=4;++d)
        sum+=grainCorrelation(band,abs(d))*max(0.0,footprint-abs(lag-float(d)));
    return sum/(footprint*footprint);
}
float haarEnergy(int band,vec2 footprint,float stepSize) {
    float x=averagedCovariance(band,footprint.x,0.0)-averagedCovariance(band,footprint.x,stepSize*footprint.x);
    float y=averagedCovariance(band,footprint.y,0.0)-averagedCovariance(band,footprint.y,stepSize*footprint.y);
    return max(0.0,x*y);
}
void considerFit(mat3 response,vec3 measured,vec3 candidate,inout vec3 best,inout float error) {
    if (any(lessThan(candidate,vec3(0))) || any(isnan(candidate)) || any(isinf(candidate))) return;
    vec3 residual=response*candidate-measured;
    float score=dot(residual,residual);
    if (score<error) {best=candidate;error=score;}
}
vec3 fitBands(mat3 response,vec3 measured) {
    // Enumerate the active sets of this three-variable nonnegative fit.
    // Normalized columns let coarse proxies fail the conditioning check
    // instead of producing large opposing, unobservable band strengths.
    vec3 scale=vec3(length(response[0]),length(response[1]),length(response[2]));
    mat3 a=mat3(response[0]/max(scale.x,1e-12),response[1]/max(scale.y,1e-12),response[2]/max(scale.z,1e-12));
    vec3 best=vec3(0);float error=dot(measured,measured);
    for (int i=0;i<3;++i) {
        vec3 candidate=vec3(0);candidate[i]=max(0.0,dot(a[i],measured));
        considerFit(a,measured,candidate,best,error);
    }
    for (int i=0;i<3;++i) for (int j=i+1;j<3;++j) {
        float c=dot(a[i],a[j]),det=1.0-c*c;
        if (det<.0001) continue;
        float x=dot(a[i],measured),y=dot(a[j],measured);
        vec3 candidate=vec3(0);candidate[i]=(x-c*y)/det;candidate[j]=(y-c*x)/det;
        considerFit(a,measured,candidate,best,error);
    }
    if (abs(determinant(a))>.001) considerFit(a,measured,inverse(a)*measured,best,error);
    return best/max(scale,vec3(1e-12));
}
void main() {
    ivec2 cell=ivec2(gl_GlobalInvocationID.xy),size=imageSize(varianceOutput).xy;
    if (any(greaterThanEqual(cell,size))) return;
    if (clearOnly) {
        for (int band=0;band<3;++band) {
            imageStore(varianceOutput,ivec3(cell,band),vec4(0,0,0,-1));
            imageStore(covarianceOutput,ivec3(cell,band),vec4(0,0,0,-1));
        }
        return;
    }
    vec2 uv=(vec2(cell)+.5)/vec2(size);
    vec2 local=(uv-rect.xy)/max(rect.zw-rect.xy,vec2(.000001));
    if (any(lessThan(local,vec2(0))) || any(greaterThan(local,vec2(1)))) return;
    vec2 dimensions=vec2(textureSize(image,0)),texel=1.0/dimensions;
    vec2 span=abs(textureRect.zw-textureRect.xy);
    vec2 lo=min(textureRect.xy,textureRect.zw)+.5*texel;
    vec2 hi=max(lo,max(textureRect.xy,textureRect.zw)-.5*texel);
    // Repeated boundary taps cannot estimate a spatial noise spectrum.
    if (any(lessThan((hi-lo)/texel,vec2(16)))) return;
    vec2 p=mix(textureRect.xy,textureRect.zw,local);
    p=(floor(p*dimensions)+.5)/dimensions;
    p=clamp(p,lo+6.0*texel,hi-10.0*texel);
    vec3 first[16],second[16],third[16];
    float brightness=0.0;
    for (int i=0;i<16;++i) {
        // Integer spacing keeps all measurements at texel centers, including
        // between native detail patches and reduced complete-photo previews.
        vec2 q=p+vec2((i%4)*4-6,(i/4)*4-6)*texel;
        vec4 a=samplePhoto(q);
        if (!(a.a>.99)) return;
        brightness+=dot(a.rgb,vec3(.2126,.7152,.0722))/16.0;
        for (int level=0;level<3;++level) {
            vec2 stepSize=texel*float(1<<level);
            vec4 b=samplePhoto(q+vec2(stepSize.x,0)),c=samplePhoto(q+vec2(0,stepSize.y)),d=samplePhoto(q+stepSize);
            if (!(min(b.a,min(c.a,d.a))>.99)) return;
            vec3 residual=noiseComponents(.5*(a.rgb-b.rgb-c.rgb+d.rgb));
            if (level==0) first[i]=residual;
            else if (level==1) second[i]=residual;
            else third[i]=residual;
        }
    }
    vec3 v1,v2,v4,c1,c2,c4;
    robustMoments(first,v1,c1);robustMoments(second,v2,c2);robustMoments(third,v4,c4);
    vec2 footprint=max(vec2(1),nativeExtent*(rect.zw-rect.xy)/max(vec2(1),span*dimensions));
    mat3 response;
    for (int band=0;band<3;++band)
        response[band]=vec3(haarEnergy(band,footprint,1),haarEnergy(band,footprint,2),haarEnergy(band,footprint,4));
    mat3 fitted=mat3(fitBands(response,vec3(v1.x,v2.x,v4.x)),
        fitBands(response,vec3(v1.y,v2.y,v4.y)),fitBands(response,vec3(v1.z,v2.z,v4.z)));
    fitted=transpose(fitted);
    for (int band=0;band<3;++band) {
        vec3 variance=fitted[band];
        vec3 correlation=band==0 ? c1 : band==1 ? c2 : c4;
        vec3 covariance=correlation*sqrt(max(vec3(0),variance.xxy*variance.yzz));
        imageStore(varianceOutput,ivec3(cell,band),vec4(variance,brightness));
        imageStore(covarianceOutput,ivec3(cell,band),vec4(covariance,brightness));
    }
}
)";
}
